    'RegisterSimpleRisk'=>'הרשמה SimpleRisk',
    'RegistrationText'=>'מופעי SimpleRisk רשומים מקבלים גישה מיידית לתוספות שדרוג ו-Secure Controls Framework (SCF). ה- Upgrade Extra מספק את היכולת לגבות ולשדרג את מופע SimpleRisk שלך בלחיצת כפתור. ה-Secure Controls Framework (SCF) Extra מספקת מסגרת בקרה משותפת המשולבת בפונקציונליות SimpleRisk Governance. עם רישום SimpleRisk, פרטי ההרשמה שלך יישלחו לשרת המארח SimpleRisk. פרטי הרישום שיסופקו ישמשו את SimpleRisk כדי להודיע ללקוחות על מהדורות חדשות ועדכוני אבטחה. פעולת הרישום של SimpleRisk תגרום לך להצטרף לתקשורת השיווקית שלנו, אך תוכל לבטל את הסכמתך בכל עת באמצעות הקישור לביטול הרשמה בתקשורת זו. SimpleRisk מכבדת את פרטיות הלקוחות שלנו והמידע שנמסר לנו באמצעות תהליך הרישום של SimpleRisk לעולם לא יימכר לצד שלישי.',
