    'ApplicabilityScopeNote' => 'החלטה זו חלה רק בתוך "{$framework}". אותה פקד יכולה להישאר רלוונטי גם במסגרת אחרת.',
    'ApplicabilityAppliesToSelected' => 'זה יירשם כנגד הפקד/ים {$n} שנבחרו בדף זה.',
